# Each track has five deliberately short, non-graphic lesson drafts. Localized copy is
# generated from this explicit content map so every seeded item is editable in the CMS.
TRACKS = [
    {
        "id": "ages-6-9", "ages": "6–9", "title": {"en":"My body, my space", "rw":"Umubiri wanjye, umwanya wanjye", "fr":"Mon corps, mon espace"},
        "description": {"en":"Simple ideas about body awareness, trusted adults and asking for help.", "rw":"Ibitekerezo byoroshye ku kumenya umubiri, abantu bakuru bizewe no gusaba ubufasha.", "fr":"Des repères simples sur le corps, les adultes de confiance et la demande d’aide."},
        "lessons": [
            ("body-awareness", {"en":"Knowing your body", "rw":"Kumenya umubiri wawe", "fr":"Connaître son corps"}, {"en":"Your body belongs to you. Learn the names for everyday body parts and notice when you feel comfortable, unsure or uncomfortable. You can ask a trusted adult questions without being blamed.", "rw":"Umubiri wawe ni uwawe. Menya amazina y’ibice by’umubiri kandi wumve igihe wisanzuye, ushidikanya cyangwa utishimiye ikintu. Ushobora kubaza umuntu mukuru wizeye utagomba kugawa.", "fr":"Ton corps t’appartient. Apprends le nom des parties du corps et remarque quand tu te sens à l’aise, incertain ou mal à l’aise. Tu peux poser des questions à un adulte de confiance sans être blâmé."}),
            ("personal-space", {"en":"Personal space and boundaries", "rw":"Umwanya bwite n’imbibi", "fr":"Espace personnel et limites"}, {"en":"Everyone deserves personal space. You may say no to unwanted touch, move away, or ask for help. A caring adult listens when you set a boundary.", "rw":"Buri wese akwiye umwanya we bwite. Ushobora kuvuga oya ku gukorwaho udashaka, kwigendera cyangwa gusaba ubufasha. Umuntu mukuru ukwitaho yumva imbibi ushyizeho.", "fr":"Chacun mérite un espace personnel. Tu peux refuser un contact non souhaité, t’éloigner ou demander de l’aide. Un adulte bienveillant écoute tes limites."}),
            ("trusted-adults", {"en":"Finding trusted adults", "rw":"Kumenya abantu bakuru bizewe", "fr":"Trouver des adultes de confiance"}, {"en":"Think of two adults who listen and help you feel safe, such as a caregiver or teacher. If the first person cannot help, keep asking another safe adult until someone listens.", "rw":"Tekereza ku bantu babiri bakuru bakumva kandi bakagufasha kumva utekanye, nk’umurezi cyangwa umwarimu. Niba uwa mbere adashoboye kugufasha, saba undi muntu mukuru wizewe kugeza igihe bakumvise.", "fr":"Pense à deux adultes qui t’écoutent et t’aident à te sentir en sécurité, comme un parent ou un enseignant. Si la première personne ne peut pas aider, demande à un autre adulte sûr."}),
            ("privacy-basics", {"en":"Keeping personal information private", "rw":"Kubika amakuru bwite", "fr":"Protéger ses informations personnelles"}, {"en":"Your full name, home location, passwords and private photos should not be shared with strangers online. Ask a trusted adult before posting or sending personal details.", "rw":"Amazina yawe yose, aho utuye, ijambo ry’ibanga n’amafoto bwite ntibigomba guhabwa abo mutaziranye kuri interineti. Banza ubaze umuntu mukuru wizeye mbere yo gushyira ahagaragara cyangwa kohereza amakuru bwite.", "fr":"Ton nom complet, ton adresse, tes mots de passe et tes photos privées ne doivent pas être partagés avec des inconnus en ligne. Demande à un adulte de confiance avant de publier des informations personnelles."}),
            ("asking-for-help", {"en":"Asking for help", "rw":"Gusaba ubufasha", "fr":"Demander de l’aide"}, {"en":"If something worries you, tell a trusted adult using your own words. You do not need to explain everything at once. Keep asking until a safe adult helps you.", "rw":"Niba hari ikikuhangayikishije, bibwire umuntu mukuru wizeye uko ubyumva. Si ngombwa gusobanura byose icyarimwe. Komeza gusaba ubufasha kugeza igihe umuntu mukuru wizewe agufashije.", "fr":"Si quelque chose t’inquiète, parle-en à un adulte de confiance avec tes propres mots. Tu n’as pas besoin de tout expliquer d’un coup. Continue à demander de l’aide jusqu’à ce qu’un adulte sûr t’écoute."}),
        ]
    },
    {
        "id":"ages-10-12", "ages":"10–12", "title":{"en":"Growing and changing", "rw":"Gukura no guhinduka", "fr":"Grandir et changer"}, "description":{"en":"Age-appropriate learning about puberty, feelings, privacy and respectful boundaries.", "rw":"Kwiga bijyanye n’imyaka ku bugimbi, ibyiyumvo, ubuzima bwite n’imbibi zirangwa no kubahana.", "fr":"Des repères adaptés à l’âge sur la puberté, les émotions, la vie privée et les limites respectueuses."},
        "lessons":[
            ("puberty-changes", {"en":"Puberty: changes happen at different times", "rw":"Ubugimbi: impinduka ziza mu bihe bitandukanye", "fr":"Puberté : les changements arrivent à des moments différents"}, {"en":"Puberty brings physical and emotional changes, and timing differs for each person. Questions are normal. A trusted caregiver or qualified health worker can explain what to expect without comparing you with others.", "rw":"Ubugimbi buzana impinduka z’umubiri n’ibyiyumvo, kandi ziza mu bihe bitandukanye kuri buri muntu. Kubaza ni ibisanzwe. Umurezi wizewe cyangwa umukozi w’ubuzima ubifitiye ubumenyi ashobora kugusobanurira utaguhuje n’abandi.", "fr":"La puberté entraîne des changements physiques et émotionnels, à des moments différents pour chacun. Les questions sont normales. Un adulte de confiance ou un professionnel de santé qualifié peut expliquer ce qui se passe sans te comparer aux autres."}),
            ("menstrual-health", {"en":"Periods and menstrual care", "rw":"Imihango n’isuku yayo", "fr":"Les règles et l’hygiène menstruelle"}, {"en":"Menstruation is a normal part of puberty for many people. Clean absorbent products, handwashing and access to a private changing place can support comfort. Severe pain or concerns deserve a conversation with a qualified health worker.", "rw":"Imihango ni igice gisanzwe cy’ubugimbi ku bantu benshi. Ibikoresho bisukuye byo kwifashisha, gukaraba intoki no kubona ahantu hihariye ho kubihindurira bifasha kwisanzura. Ububabare bukabije cyangwa impungenge bikwiye kuganirwaho n’umukozi w’ubuzima ubifitiye ubumenyi.", "fr":"Les règles font partie de la puberté pour beaucoup de personnes. Des protections propres, le lavage des mains et un lieu privé pour les changer favorisent le confort. Une douleur intense ou une inquiétude mérite d’être abordée avec un professionnel de santé."}),
            ("feelings-self-esteem", {"en":"Feelings and self-esteem", "rw":"Ibyiyumvo no kwiyubaha", "fr":"Émotions et estime de soi"}, {"en":"Feelings can change as you grow. Naming a feeling, taking a calm breath and talking with someone you trust can help. Your value does not depend on appearance, popularity or being the same as others.", "rw":"Ibyiyumvo bishobora guhinduka uko ukura. Kuvuga uko wiyumva, guhumeka utuje no kuganira n’uwo wizeye birafasha. Agaciro kawe ntigashingira ku isura, gukundwa n’abantu cyangwa kumera nk’abandi.", "fr":"Les émotions peuvent changer en grandissant. Nommer une émotion, respirer calmement et parler avec une personne de confiance peut aider. Ta valeur ne dépend ni de ton apparence, ni de ta popularité, ni du fait d’être comme les autres."}),
            ("consent-boundaries", {"en":"Respecting boundaries", "rw":"Kubaha imbibi", "fr":"Respecter les limites"}, {"en":"A boundary is a limit someone communicates about their body, belongings, time or privacy. Ask before touching or borrowing, accept no without pressure, and seek a trusted adult if a situation feels unsafe.", "rw":"Urubibi ni icyo umuntu agaragaza ku mubiri we, ibye, igihe cye cyangwa ubuzima bwe bwite. Baza mbere yo gukoraho cyangwa kuguriza, wemere igisubizo cya oya utagombye guhatiriza, kandi ushake umuntu mukuru wizewe niba ibintu bitameze neza.", "fr":"Une limite est ce qu’une personne exprime au sujet de son corps, de ses affaires, de son temps ou de sa vie privée. Demande avant de toucher ou d’emprunter, accepte un refus sans insister et cherche un adulte de confiance si tu ne te sens pas en sécurité."}),
            ("cyberbullying", {"en":"Online kindness and cyberbullying", "rw":"Kugira neza kuri interineti no gutotezwa", "fr":"Bienveillance en ligne et cyberharcèlement"}, {"en":"Do not forward hurtful messages or images. Save only what is safe and necessary, block or report the account, and tell a trusted adult. Do not retaliate; the person targeted is not to blame.", "rw":"Ntukohereze abandi ubutumwa cyangwa amashusho bibababaza. Bika gusa ibikenewe kandi bitekanye, hagarika cyangwa utangaze konti, ubwire umuntu mukuru wizeye. Ntugahime; uwibasiwe si we ubigizemo uruhare.", "fr":"Ne transfère pas les messages ou images blessants. Garde uniquement ce qui est nécessaire et sûr, bloque ou signale le compte et parle à un adulte de confiance. Ne te venge pas ; la personne ciblée n’est pas responsable."}),
        ]
    },
    {
        "id":"ages-13-15", "ages":"13–15", "title":{"en":"Health, respect and online safety", "rw":"Ubuzima, kubahana n’umutekano kuri interineti", "fr":"Santé, respect et sécurité en ligne"}, "description":{"en":"Build health literacy, communication skills and safer digital habits.", "rw":"Kongera ubumenyi ku buzima, ubuhanga bwo kuganira n’ingeso zitekanye kuri interineti.", "fr":"Renforcer la culture de santé, la communication et les habitudes numériques plus sûres."},
        "lessons":[
            ("health-information", {"en":"Checking health information", "rw":"Gusuzuma amakuru y’ubuzima", "fr":"Vérifier les informations de santé"}, {"en":"Health claims online can be incomplete or misleading. Check who published them, when they were updated and whether a qualified source supports them. For personal health concerns, ask a qualified health professional.", "rw":"Amakuru y’ubuzima yo kuri interineti ashobora kuba atuzuye cyangwa ayobya. Reba uyatangaje, igihe yavugururiwe n’uko ashyigikiwe n’isoko ryizewe. Ku kibazo cyawe bwite cy’ubuzima, baza umukozi w’ubuzima ubifitiye ubumenyi.", "fr":"Les informations de santé en ligne peuvent être incomplètes ou trompeuses. Vérifie qui les publie, leur date de mise à jour et si une source qualifiée les confirme. Pour une question personnelle de santé, consulte un professionnel qualifié."}),
            ("healthy-relationships", {"en":"Respectful relationships", "rw":"Imibanire irangwa no kubahana", "fr":"Relations respectueuses"}, {"en":"Healthy relationships include respect, honest communication and room for each person to make choices. Control, threats, humiliation or pressure are warning signs. Talk with a safe adult or qualified support service if you are concerned.", "rw":"Imibanire myiza irangwa no kubahana, kuganira ukuri no guha buri wese umwanya wo gufata ibyemezo. Kugenzura undi, kumutera ubwoba, kumusuzugura cyangwa kumuhatira ni ibimenyetso byo kwitondera. Ganira n’umuntu mukuru wizewe cyangwa serivisi ibifitiye ubumenyi.", "fr":"Une relation saine repose sur le respect, une communication honnête et la liberté de décision de chacun. Le contrôle, les menaces, l’humiliation ou la pression sont des signes préoccupants. Parle à un adulte sûr ou à un service qualifié."}),
            ("consent-communication", {"en":"Consent and communication", "rw":"Kwemeranya no kuganira", "fr":"Consentement et communication"}, {"en":"Consent means a freely given, informed and ongoing agreement. Silence, fear, pressure or a previous yes is not consent. You can change your mind. Laws and safeguarding rules matter; ask a qualified local professional when unsure.", "rw":"Kwemeranya bisobanura kwemera wisanzuye, uzi neza kandi bikomeza kubahirizwa. Guceceka, ubwoba, guhatirwa cyangwa kuba warigeze kuvuga yego si ukwemera. Ushobora guhindura igitekerezo. Amategeko n’amabwiriza yo kurinda abantu ni ingenzi; baza inzobere yo mu gace igihe ushidikanya.", "fr":"Le consentement est un accord libre, éclairé et continu. Le silence, la peur, la pression ou un oui antérieur ne constituent pas un consentement. Tu peux changer d’avis. Les lois et les règles de protection comptent ; demande conseil à un professionnel local qualifié en cas de doute."}),
            ("digital-footprint", {"en":"Privacy and digital footprints", "rw":"Ubuzima bwite n’ibisigara kuri interineti", "fr":"Vie privée et traces numériques"}, {"en":"Posts, location data and shared-device history can remain accessible. Review privacy settings, use unique passwords and sign out on shared devices. If someone pressures you to share private material, stop, preserve your safety and seek trusted help.", "rw":"Ibyo ushyira kuri interineti, amakuru y’aho uri n’amateka yo ku gikoresho musangiye bishobora kuguma bigaragara. Suzuma igenamiterere ry’ubuzima bwite, koresha amagambo y’ibanga atandukanye kandi usohoke kuri mudasobwa musangiye. Niba hari uguhatira kohereza ibintu bwite, hagarika, urinde umutekano wawe kandi ushake ubufasha bwizewe.", "fr":"Les publications, la localisation et l’historique d’un appareil partagé peuvent rester accessibles. Vérifie les paramètres de confidentialité, utilise des mots de passe uniques et déconnecte-toi des appareils partagés. Si quelqu’un te pousse à partager du contenu privé, arrête, protège ta sécurité et cherche une aide de confiance."}),
            ("getting-healthcare", {"en":"Finding respectful health care", "rw":"Kubona serivisi z’ubuzima zubaha umuntu", "fr":"Trouver des soins respectueux"}, {"en":"A qualified health worker can explain available services and answer questions without promising that every service is available everywhere. You may ask about privacy, costs, consent and what information is recorded before choosing care.", "rw":"Umukozi w’ubuzima ubifitiye ubumenyi ashobora gusobanura serivisi zihari no gusubiza ibibazo, ariko ntibivuze ko serivisi zose ziboneka hose. Ushobora kubaza ibijyanye n’ibanga, ikiguzi, ukwemera n’amakuru yandikwa mbere yo guhitamo kwivuza.", "fr":"Un professionnel de santé qualifié peut expliquer les services disponibles, sans garantir qu’ils existent partout. Tu peux poser des questions sur la confidentialité, les coûts, le consentement et les informations conservées avant de choisir des soins."}),
        ]
    },
    {
        "id":"ages-16-19", "ages":"16–19", "title":{"en":"Informed choices and wellbeing", "rw":"Ibyemezo bisobanutse n’imibereho myiza", "fr":"Choix éclairés et bien-être"}, "description":{"en":"Explore informed health decisions, prevention, digital rights and help-seeking.", "rw":"Menya gufata ibyemezo by’ubuzima usobanukiwe, kwirinda, uburenganzira bwa digitale no gushaka ubufasha.", "fr":"Explorer les décisions de santé éclairées, la prévention, les droits numériques et la demande d’aide."},
        "lessons":[
            ("reproductive-health", {"en":"Reproductive health basics", "rw":"Iby’ibanze ku buzima bw’imyororokere", "fr":"Bases de la santé reproductive"}, {"en":"Reproductive health includes physical, emotional and social wellbeing. Reliable information can help you prepare questions for a qualified provider. This lesson is educational and cannot diagnose a condition or replace care.", "rw":"Ubuzima bw’imyororokere bukubiyemo imibereho myiza y’umubiri, ibyiyumvo n’imibanire. Amakuru yizewe yagufasha gutegura ibibazo byo kubaza umukozi w’ubuzima ubifitiye ubumenyi. Iri somo ni iry’ubumenyi rusange; ntirisuzuma indwara cyangwa ngo risimbure kwivuza.", "fr":"La santé reproductive comprend le bien-être physique, émotionnel et social. Des informations fiables peuvent aider à préparer des questions pour un professionnel qualifié. Cette leçon est éducative ; elle ne diagnostique pas et ne remplace pas les soins."}),
            ("contraception", {"en":"Understanding contraception information", "rw":"Gusobanukirwa amakuru ku kuboneza urubyaro", "fr":"Comprendre les informations sur la contraception"}, {"en":"Contraceptive methods differ in use, benefits, limits and availability. A qualified health professional can explain options and answer personal questions confidentially within applicable rules. Do not rely on this general lesson to choose a method for yourself.", "rw":"Uburyo bwo kuboneza urubyaro buratandukanye mu mikoreshereze, ibyiza, imipaka n’aho buboneka. Umukozi w’ubuzima ubifitiye ubumenyi ashobora gusobanura amahitamo no gusubiza ibibazo byawe bwite mu ibanga hakurikijwe amategeko. Ntukishingikirize kuri iri somo rusange ngo uhitemo uburyo bwawe.", "fr":"Les méthodes contraceptives diffèrent par leur usage, leurs avantages, leurs limites et leur disponibilité. Un professionnel de santé qualifié peut expliquer les options et répondre aux questions personnelles selon les règles applicables. N’utilise pas cette leçon générale pour choisir une méthode."}),
            ("sti-hiv", {"en":"STI and HIV: prevention and testing", "rw":"Indwara zandurira mu mibonano n’agakoko gatera SIDA: kwirinda no kwisuzumisha", "fr":"IST et VIH : prévention et dépistage"}, {"en":"Many infections can be prevented or treated, and testing is a health service rather than a judgment. A qualified clinic can explain locally available prevention, testing and treatment. Seek timely professional care for a personal concern.", "rw":"Indwara nyinshi zirindwa cyangwa zikavurwa, kandi kwisuzumisha ni serivisi y’ubuzima, si ukugaya umuntu. Ivuriro rifite abakozi babifitiye ubumenyi risobanura uburyo bwo kwirinda, kwisuzumisha no kuvura buboneka hafi yawe. Ku kibazo cyawe bwite, shaka ubuvuzi hakiri kare.", "fr":"De nombreuses infections peuvent être évitées ou traitées, et le dépistage est un service de santé, pas un jugement. Une clinique qualifiée peut expliquer la prévention, le dépistage et les traitements disponibles localement. Consulte rapidement un professionnel pour une préoccupation personnelle."}),
            ("coercion-and-abuse", {"en":"Recognizing coercion and abuse", "rw":"Kumenya guhatirwa n’ihohoterwa", "fr":"Reconnaître la coercition et les abus"}, {"en":"Pressure, threats, unwanted monitoring and control can be harmful. If you are worried about your safety, consider reaching a trusted person or verified service from a safe device. You do not have to share details here to learn about support.", "rw":"Guhatirwa, guterwa ubwoba, kugenzurwa utabishaka no kwamburwa ubwisanzure bishobora kukugiraho ingaruka mbi. Niba uhangayikishijwe n’umutekano wawe, gerageza kugana umuntu wizeye cyangwa serivisi yagenzuwe ukoresheje igikoresho gitekanye. Ntugomba gusangiza aha amakuru yawe bwite kugira ngo umenye aho ubufasha buri.", "fr":"La pression, les menaces, la surveillance non souhaitée et le contrôle peuvent être nuisibles. Si ta sécurité t’inquiète, essaie de joindre une personne de confiance ou un service vérifié depuis un appareil sûr. Tu n’as pas besoin de raconter ton vécu ici pour connaître les soutiens possibles."}),
            ("misinformation", {"en":"Responding to health misinformation", "rw":"Gusubiza amakuru ayobya ku buzima", "fr":"Réagir à la désinformation en santé"}, {"en":"Pause before forwarding a surprising claim. Check a qualified source, the date and the evidence; look for agreement across trusted sources. If sources disagree, say what is uncertain and ask a qualified professional.", "rw":"Banza utekereze mbere yo kohereza abandi amakuru atangaje. Suzuma isoko rifite ubumenyi, itariki n’ibimenyetso; reba niba andi masoko yizewe abyemeranyaho. Niba amasoko atavuga kimwe, vuga ibitarasobanuka maze ubaze inzobere.", "fr":"Prends le temps de vérifier avant de transférer une affirmation surprenante. Consulte une source qualifiée, la date et les éléments de preuve ; compare plusieurs sources fiables. En cas de désaccord, précise ce qui reste incertain et demande conseil à un professionnel."}),
        ]
    },
    {
        "id":"ages-20-24", "ages":"20–24", "title":{"en":"Health navigation and relationships", "rw":"Gushaka serivisi z’ubuzima n’imibanire", "fr":"Parcours de santé et relations"}, "description":{"en":"Practical learning about care navigation, reproductive planning, safety and peer education.", "rw":"Kwiga uburyo bufatika bwo kubona serivisi, igenamigambi ry’imyororokere, umutekano no kwigisha urungano.", "fr":"Apprentissages pratiques sur l’accès aux soins, la planification reproductive, la sécurité et l’éducation par les pairs."},
        "lessons":[
            ("care-navigation", {"en":"Navigating health services", "rw":"Gushaka serivisi z’ubuzima", "fr":"S’orienter dans les services de santé"}, {"en":"Before a visit, note your questions and ask about service scope, costs, confidentiality and follow-up. Confirm current availability directly with the provider; a directory entry is not a guarantee of a service or appointment.", "rw":"Mbere yo kujya kwa muganga, andika ibibazo byawe maze ubaze serivisi zitangwa, ikiguzi, ibanga n’uko ukurikirana. Emeza ko serivisi ihari ubaza uyitanga; kuba iri ku rutonde ntibihamya ko ihari cyangwa ko uzabona gahunda.", "fr":"Avant une consultation, note tes questions et renseigne-toi sur les services, les coûts, la confidentialité et le suivi. Confirme directement la disponibilité auprès du prestataire ; une fiche d’annuaire ne garantit ni service ni rendez-vous."}),
            ("reproductive-planning", {"en":"Reproductive planning conversations", "rw":"Kuganira ku igenamigambi ry’imyororokere", "fr":"Discuter de la planification reproductive"}, {"en":"People may have different goals and timelines. A respectful conversation makes space for each person’s choices and safety. For method-specific guidance, speak with a qualified health professional about available options and individual needs.", "rw":"Abantu bashobora kugira intego n’ibihe bitandukanye. Ikiganiro cyubaha buri wese giha umwanya amahitamo ye n’umutekano. Ku nama zerekeye uburyo runaka, ganira n’umukozi w’ubuzima ubifitiye ubumenyi ku mahitamo ahari n’ibyo ukeneye.", "fr":"Les personnes peuvent avoir des objectifs et des calendriers différents. Une conversation respectueuse laisse de la place aux choix et à la sécurité de chacun. Pour des conseils sur une méthode, parle à un professionnel qualifié des options disponibles et de tes besoins."}),
            ("supporting-peers", {"en":"Supporting a friend without taking over", "rw":"Gushyigikira inshuti utayifatira ibyemezo", "fr":"Soutenir un proche sans décider à sa place"}, {"en":"Listen without blame, ask what kind of help the person wants and respect their choices. Do not promise secrecy you cannot keep or investigate on your own. If immediate danger is present, seek appropriate emergency help.", "rw":"Umva utagaya, ubaze ubufasha uwo muntu akeneye kandi wubahe amahitamo ye. Ntusezeranye kubika ibanga udashobora kubahiriza cyangwa ngo wigire umushakashatsi. Niba hari akaga kihutirwa, shaka ubufasha bwihutirwa bukwiye.", "fr":"Écoute sans blâmer, demande quel soutien la personne souhaite et respecte ses choix. Ne promets pas un secret que tu ne peux pas garder et ne mène pas d’enquête toi-même. En cas de danger immédiat, cherche une aide d’urgence adaptée."}),
            ("digital-rights", {"en":"Digital rights and safer accounts", "rw":"Uburenganzira kuri interineti na konti zitekanye", "fr":"Droits numériques et comptes plus sûrs"}, {"en":"Use unique passwords and multifactor authentication where possible. Review account recovery and location-sharing settings, and plan how to use shared devices safely. Privacy tools reduce exposure but cannot guarantee complete anonymity.", "rw":"Koresha amagambo y’ibanga atandukanye n’uburyo bwo kwemeza intambwe nyinshi igihe bishoboka. Suzuma uburyo bwo kugarura konti n’igenamiterere ry’aho uherereye, kandi utegure uko wakoresha ibikoresho musangiye neza. Ibikoresho by’ibanga bigabanya ibyago ariko ntibyemeza ko utamenyekana burundu.", "fr":"Utilise des mots de passe uniques et l’authentification multifacteur si possible. Vérifie les paramètres de récupération et de localisation, et organise un usage sûr des appareils partagés. Les outils de confidentialité réduisent l’exposition sans garantir l’anonymat complet."}),
            ("violence-prevention", {"en":"Preventing violence in everyday settings", "rw":"Gukumira ihohoterwa mu buzima bwa buri munsi", "fr":"Prévenir la violence au quotidien"}, {"en":"Prevention includes challenging disrespectful behaviour safely, building supportive norms and knowing where qualified help is available. A bystander should not intervene in a way that increases danger; seek trained support when needed.", "rw":"Gukumira ihohoterwa bikubiyemo kwamagana imyitwarire yo gusuzugura mu mutekano, kubaka imigenzo yo gushyigikirana no kumenya aho ubufasha bufite ubumenyi buboneka. Umuntu ubibonye ntagomba gutabara mu buryo bwongera akaga; igihe bikenewe, shaka abakozi babihuguriwe.", "fr":"La prévention consiste notamment à remettre en question les comportements irrespectueux sans danger, à promouvoir le soutien mutuel et à connaître les services qualifiés. Un témoin ne doit pas intervenir d’une manière qui accroît le risque ; cherche de l’aide formée si nécessaire."}),
        ]
    },
    {
        "id":"ages-25-plus", "ages":"25+", "title":{"en":"Caregiving and community wellbeing", "rw":"Kurera no guteza imbere imibereho y’umuryango", "fr":"Accompagnement et bien-être communautaire"}, "description":{"en":"Resources for caregivers, families and community educators, with a focus on dignity and safe referral.", "rw":"Ibikoresho by’abarezi, imiryango n’abigisha b’umuryango, byibanda ku cyubahiro no kohereza ahari ubufasha hatekanye.", "fr":"Des ressources pour les aidants, les familles et les éducateurs communautaires, axées sur la dignité et l’orientation sûre."},
        "lessons":[
            ("caregiver-conversations", {"en":"Talking with young people about health", "rw":"Kuganira n’urubyiruko ku buzima", "fr":"Parler de santé avec les jeunes"}, {"en":"Use calm, age-appropriate language and invite questions without shame. Listen before advising, acknowledge uncertainty, and connect the young person with a qualified service when a question needs professional care.", "rw":"Koresha imvugo ituje kandi ijyanye n’imyaka, uteze amatwi ibibazo nta soni. Banza wumve mbere yo kugira inama, wemere ibyo utazi, kandi uhuze urubyiruko na serivisi ibifitiye ubumenyi igihe hakenewe ubuvuzi bw’inzobere.", "fr":"Utilise un langage calme et adapté à l’âge et accueille les questions sans honte. Écoute avant de conseiller, reconnais ce qui est incertain et oriente vers un service qualifié lorsqu’un soin professionnel est nécessaire."}),
            ("child-safeguarding", {"en":"Responding to a safeguarding concern", "rw":"Gusubiza ku mpungenge zo kurinda umwana", "fr":"Réagir à une préoccupation de protection"}, {"en":"Stay calm, listen, avoid leading questions and do not promise absolute secrecy. Follow your organization’s approved safeguarding protocol and involve the designated trained officer. Do not investigate or confront a suspected person yourself.", "rw":"Tuza, umve, wirinde ibibazo biyobora igisubizo kandi ntusezeranye kubika ibanga burundu. Kurikiza amabwiriza yemejwe yo kurinda abantu kandi ubimenyeshe umukozi wabihuguriwe wagenewe. Ntukore iperereza cyangwa ngo uhangane n’uwo ukeka ubwawe.", "fr":"Reste calme, écoute, évite les questions suggestives et ne promets pas un secret absolu. Suis le protocole de protection approuvé par ton organisation et contacte la personne formée désignée. Ne mène pas d’enquête et ne confronte pas toi-même une personne soupçonnée."}),
            ("community-health-literacy", {"en":"Community health literacy", "rw":"Ubumenyi ku buzima mu muryango", "fr":"Culture de santé communautaire"}, {"en":"Share information from identifiable, qualified sources and show its date. Separate general education from individual medical advice. Invite people to ask a qualified local provider about personal decisions or urgent symptoms.", "rw":"Sangiza abantu amakuru ava ku masoko azwi kandi afite ubumenyi, ugaragaze n’itariki yayo. Tandukanya inyigisho rusange n’inama yo kwivuza ku muntu ku giti cye. Shishikariza abantu kubaza umukozi w’ubuzima waho ufite ubumenyi ku byemezo byabo cyangwa ibimenyetso byihutirwa.", "fr":"Partage des informations issues de sources qualifiées et identifiables, avec leur date. Distingue l’éducation générale des conseils médicaux individuels. Encourage chacun à consulter un professionnel local qualifié pour une décision personnelle ou un symptôme urgent."}),
            ("supporting-survivors", {"en":"Supporting someone affected by violence", "rw":"Gushyigikira uwahuye n’ihohoterwa", "fr":"Soutenir une personne touchée par la violence"}, {"en":"Believe the person, listen without blame and ask what would help them feel safer. Do not pressure them to report, share details or confront anyone. Explain confidentiality limits before sharing information and offer verified services.", "rw":"Emera ibyo umuntu akubwiye, umutege amatwi utamugaya kandi umubaze icyamufasha kumva atekanye. Ntumuhatire gutanga raporo, gusangiza amakuru cyangwa guhangana n’umuntu. Sobanura imipaka y’ibanga mbere yo gusangiza amakuru kandi werekeze kuri serivisi zagenzuwe.", "fr":"Crois la personne, écoute sans la blâmer et demande ce qui pourrait l’aider à se sentir plus en sécurité. Ne la pousse pas à signaler, raconter des détails ou confronter quelqu’un. Explique les limites de confidentialité avant tout partage et propose des services vérifiés."}),
            ("referral-practice", {"en":"Making a safe referral", "rw":"Kohereza umuntu ahari ubufasha hatekanye", "fr":"Orienter vers un service de manière sûre"}, {"en":"Ask permission before sharing information where possible. Confirm the receiving service’s scope, hours and current availability directly. Share only what is necessary, explain next steps and do not guarantee an outcome you cannot control.", "rw":"Aho bishoboka, banza usabe uruhushya mbere yo gusangiza amakuru. Emeza serivisi, amasaha n’uko ikora ubu ubaza uyitanga. Sangiza gusa amakuru akenewe, usobanure intambwe zikurikira kandi ntusezeranye igisubizo udashobora kugenzura.", "fr":"Dans la mesure du possible, demande l’accord avant de partager des informations. Vérifie directement le champ d’action, les horaires et la disponibilité du service. Ne partage que le nécessaire, explique la suite et ne garantis pas un résultat que tu ne maîtrises pas."}),
        ]
    },
]

