FAQS = {
 "en":[
  ("privacy","Will this website keep me anonymous?","No absolute anonymity is promised. Public learning does not require an account and progress stays in this browser, but your device, network or browser may keep activity records. Avoid entering identifying details."),
  ("medical-advice","Can Cyizere diagnose a health problem?","No. Cyizere is an educational assistant, not a clinician. It should not diagnose or prescribe. For a personal health concern, contact a qualified health worker."),
  ("consent","What does consent mean?","Consent is freely given, informed and ongoing agreement. Silence, pressure, fear or a previous yes is not consent. Local laws and safeguarding rules also apply."),
  ("online-safety","What can I do if someone harasses me online?","If safe, stop replying, block or report the account, save only necessary evidence, review privacy settings and tell a trusted person. Do not forward intimate images. Seek urgent help if you are in immediate danger."),
  ("support","Does this platform provide live human support?","You can submit an encrypted text-chat request when the service is configured. A support assistant must accept it first, and response times depend on staff availability. It is not an emergency or crisis service. The chat asks for your full name and exact age, and stores encrypted messages and media so you can resume later. Do not share details you do not want assigned staff to read."),
 ],
 "rw":[
  ("privacy","Uru rubuga ruzampa ubwirinzi bw’uko ntazamenyekana?","Nta bwo twizeza ko utazamenyekana na gato. Ntukeneye konti ngo usome amasomo kandi aho ugeze habikwa muri uru rubuga rwawe, ariko igikoresho, umuyoboro wa interineti cyangwa porogaramu bishobora kubika amateka. Irinde gutanga amakuru akuranga."),
  ("medical-advice","Cyizere ishobora gusuzuma indwara?","Oya. Cyizere itanga inyigisho gusa, si umuganga. Ntigomba gusuzuma cyangwa kwandikira umuntu imiti. Ku kibazo cy’ubuzima cyawe, hamagara umukozi w’ubuzima ubifitiye ubumenyi."),
  ("consent","Kwemeranya bisobanura iki?","Kwemeranya ni ukwemera wisanzuye, usobanukiwe kandi gukomeza kubahirizwa. Guceceka, guhatirwa, ubwoba cyangwa kuba warigeze kuvuga yego si ukwemera. Amategeko n’amabwiriza yo kurinda abantu na byo birakurikizwa."),
  ("online-safety","Nakora iki igihe umuntu antoteza kuri interineti?","Niba bitekanye, hagarika kumusubiza, hagarika cyangwa utangaze konti, bika gusa ibimenyetso bikenewe, genzura ibanga maze ubwire umuntu wizeye. Ntukohereze abandi amafoto y’ibanga. Niba hari akaga kihutirwa, shaka ubufasha."),
  ("support","Uru rubuga rutanga ubufasha bw’umuntu ako kanya?","Ushobora kohereza ubusabe bw’ikiganiro kibitswe igihe serivisi iteguye. Umufasha ni we ubanza kubwakira, kandi igihe cyo gusubizwa giterwa n’abakozi bari ku kazi. Si serivisi y’ubutabazi. Ikiganiro kibaza amazina yawe yose n’imyaka nyayo kandi kibika ubutumwa n’amafoto mu buryo bwabitswe kugira ngo uzongere ukigumane. Ntushyiremo amakuru utifuza ko umukozi wagenewe ikiganiro amenya."),
 ],
 "fr":[
  ("privacy","Ce site me garantit-il l’anonymat ?","Non, l’anonymat absolu n’est pas garanti. Aucun compte n’est nécessaire pour apprendre et votre progression reste dans ce navigateur, mais l’appareil, le réseau ou le navigateur peuvent conserver des traces. Évitez les informations identifiantes."),
  ("medical-advice","Cyizere peut-il diagnostiquer un problème de santé ?","Non. Cyizere fournit des informations éducatives et n’est pas un professionnel de santé. Il ne doit ni diagnostiquer ni prescrire. Pour une question personnelle, contactez un professionnel qualifié."),
  ("consent","Que signifie le consentement ?","Le consentement est un accord libre, éclairé et continu. Le silence, la pression, la peur ou un oui antérieur ne constituent pas un consentement. Les lois locales et règles de protection s’appliquent également."),
  ("online-safety","Que faire en cas de harcèlement en ligne ?","Si vous pouvez le faire sans danger, cessez de répondre, bloquez ou signalez le compte, conservez seulement les éléments nécessaires, vérifiez vos paramètres et parlez à une personne de confiance. Ne transférez pas d’images intimes. En cas de danger immédiat, cherchez de l’aide."),
  ("support","Cette plateforme offre-t-elle un soutien humain en direct ?","Vous pouvez envoyer une demande de chat chiffré lorsque le service est configuré. Un assistant doit l’accepter d’abord et le délai dépend du personnel disponible. Ce n’est pas un service d’urgence ou de crise. Le chat demande votre nom complet et votre âge exact, puis conserve les messages et médias chiffrés pour une reprise ultérieure. N’incluez pas d’informations que vous ne souhaitez pas partager avec le membre affecté."),
 ]
}

GUIDES = {
 "en":[
  ("digital-safety-guide","Digital safety: a short checklist","Use a unique passphrase for each account, turn on multifactor authentication where available, review recovery and location settings, sign out of shared devices and pause before opening unexpected links. These steps reduce risk but cannot guarantee safety. If someone is coercing you online, seek help from a trusted person or verified service."),
  ("gbv-support-guide","Supporting someone who shares a concern","Listen without blame. Ask what the person wants and what would help them feel safer. Do not pressure them to report, provide details or confront anyone. Explain confidentiality limits before sharing information. If there is immediate danger, use appropriate verified emergency support."),
  ("srhr-guide","Finding reliable health information","Check the source, date and evidence behind health information. General educational content cannot diagnose or replace qualified care. For personal decisions, ask a qualified local health professional about available services, privacy, costs and follow-up."),
 ],
 "rw":[
  ("digital-safety-guide","Umutekano kuri interineti: urutonde rugufi","Koresha ijambo ry’ibanga ridasubirwamo kuri buri konti, fungura uburyo bwo kwemeza intambwe nyinshi igihe buhari, genzura amakuru yo kugarura konti n’aho uherereye, sohoka ku bikoresho musangiye kandi banza utekereze mbere yo gufungura umurongo utunguranye. Izi ntambwe zigabanya ibyago ariko ntizizeza umutekano wuzuye. Niba umuntu aguhatira kuri interineti, shaka umuntu wizeye cyangwa serivisi yagenzuwe."),
  ("gbv-support-guide","Gushyigikira umuntu ugusangije impungenge","Umutege amatwi utamugaya. Mubaze icyo ashaka n’icyamufasha kumva atekanye. Ntumuhatire gutanga raporo, gutanga amakuru arambuye cyangwa guhangana n’umuntu. Sobanura imipaka y’ibanga mbere yo gusangiza amakuru. Niba hari akaga kihutirwa, shaka ubufasha bwihutirwa bwagenzuwe."),
  ("srhr-guide","Kubona amakuru yizewe ku buzima","Suzuma isoko, itariki n’ibimenyetso by’amakuru y’ubuzima. Inyigisho rusange ntizisuzuma indwara cyangwa ngo zisimbure ubuvuzi bufite ubumenyi. Ku byemezo byawe bwite, baza umukozi w’ubuzima waho ufite ubumenyi ku serivisi zihari, ibanga, ikiguzi n’uko ukurikirana."),
 ],
 "fr":[
  ("digital-safety-guide","Sécurité numérique : liste de vérification","Utilisez une phrase de passe unique pour chaque compte, activez l’authentification multifacteur si elle est disponible, vérifiez les paramètres de récupération et de localisation, déconnectez-vous des appareils partagés et réfléchissez avant d’ouvrir un lien inattendu. Ces mesures réduisent certains risques sans garantir la sécurité. En cas de coercition en ligne, cherchez une personne de confiance ou un service vérifié."),
  ("gbv-support-guide","Soutenir une personne qui se confie","Écoutez sans blâmer. Demandez ce que la personne souhaite et ce qui l’aiderait à se sentir plus en sécurité. Ne la poussez pas à signaler, à raconter des détails ou à confronter quelqu’un. Expliquez les limites de confidentialité avant de partager des informations. En cas de danger immédiat, utilisez un service d’urgence vérifié."),
  ("srhr-guide","Trouver des informations de santé fiables","Vérifiez la source, la date et les éléments de preuve des informations de santé. Un contenu éducatif général ne peut ni diagnostiquer ni remplacer des soins qualifiés. Pour une décision personnelle, demandez à un professionnel local les services disponibles, la confidentialité, les coûts et le suivi."),
 ]
}

